mapper.select:
/* seq v1/generic selectCurrent */
SELECT ${cfg.valueColumn}
  FROM ${cfg.table}
 WHERE ${cfg.tableNameColumn}  = #{key.table}
   AND ${cfg.columnNameColumn} = #{key.column}

/* seq v1/generic selectForUpdate */
SELECT COALESCE(${cfg.valueColumn}, #{initial})
  FROM ${cfg.table}
 WHERE ${cfg.tableNameColumn}  = #{key.table}
   AND ${cfg.columnNameColumn} = #{key.column}
   FOR UPDATE

mapper.update:
/* seq v1/generic increment */
UPDATE ${cfg.table}
   SET ${cfg.valueColumn} = COALESCE(${cfg.valueColumn}, #{initial}) + #{count}
 WHERE ${cfg.tableNameColumn}  = #{key.table}
   AND ${cfg.columnNameColumn} = #{key.column}

mapper.insert:
/* seq v1/generic insertRow */
INSERT INTO ${cfg.table} (${cfg.tableNameColumn}, ${cfg.columnNameColumn}, ${cfg.valueColumn})
VALUES (#{key.table}, #{key.column}, #{value})

mapper.update:
/* seq v1/generic setValue */
UPDATE ${cfg.table}
   SET ${cfg.valueColumn} = #{value}
 WHERE ${cfg.tableNameColumn}  = #{key.table}
   AND ${cfg.columnNameColumn} = #{key.column}

mapper.select:
/* seq v1/generic selectAll */
SELECT ${cfg.tableNameColumn}  AS SEQ_TBL
     , ${cfg.columnNameColumn} AS SEQ_COL
     , ${cfg.valueColumn}      AS SEQ_VAL
  FROM ${cfg.table}
 ORDER BY 1, 2
